window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0de9f46b40d3ca12"]={"versions": [{"id": "FIG-0de9f46b40d3ca12", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Interaktions- und Datenflussdiagramm im Kontext der AUTOSAR Classic Diagnostic Stack-Architektur. Das Diagramm illustriert die Abwicklung des UDS-Dienstes 0x19 (ReadDTCInformation) mit Subfunktion 0x05 (reportDTCSnapshotRecordByRecordNumber) zwischen externem Diagnosetester, Diagnostic Communication Manager (DCM) und Diagnostic Event Manager (DEM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>External Tester</strong>: Externes Diagnosewerkzeug, sendet UDS-Anfragen und empfängt UDS-Antworten.</li>\n<li><strong>DCM (Diagnostic Communication Manager)</strong>: Protokollhandler für Diagnoseanfragen auf Service-Ebene.</li>\n<li><strong>DEM (Diagnostic Event Manager)</strong>: Diagnosespeicher-Modul inklusive <code>Event memory</code> mit Tabellenstruktur für DTCs (<code>DTC1</code>, <code>DTC2</code>, <code>free</code>) und zugeordnete Freeze-Frame-Datensätze (<code>FreezeFrame (1st set)</code>, <code>FreezeFrame (2nd set)</code>).</li>\n<li><strong>Schnittstellen DCM <-> DEM</strong>:</li>\n<li><code>Dem_GetDTCOfFreezeFrameRecord</code>: Funktionsaufruf zur Ermittlung des DTC anhand der Snapshot-Record-Nummer; Rückgabe: <code>DTC</code>.</li>\n<li><code>Dem_GetFreezeFrameDataIdentifiersByDTC</code>: Abfrage der Datenidentifikatoren (DIDs) für den DTC; Rückgabe: <code>List of DataIDs</code>.</li>\n<li><code>Dem_DisableDTCRecordUpdate</code>: Sperren der Aktualisierung des Snapshot-Datensatzes im DEM.</li>\n<li><code>Dem_GetFreezeFrameDataByDTC</code>: Auslesen der Datensatzinhalte; Rückgabe: <code>Snapshot record(s)</code>.</li>\n<li><code>Dem_EnableDTCRecordUpdate</code>: Freigabe der Datensatz-Aktualisierung im DEM.</li>\n<li><strong>UDS-Nachrichten</strong>:</li>\n<li>Request: <code>$19 $05 (RecordNumber)</code></li>\n<li>Response: <code>$59 $05 (DTC + DTCStatus + RecordNumber + Number of Identifiers + SnapshotData)</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der External Tester sendet die Diagnoseanfrage <code>Request: $19 $05 (RecordNumber)</code> an den DCM.</li>\n<li>Der DCM ruft <code>Dem_GetDTCOfFreezeFrameRecord</code> am DEM auf und erhält den zugehörigen <code>DTC</code> zurück.</li>\n<li>Der DCM fragt über <code>Dem_GetFreezeFrameDataIdentifiersByDTC</code> die DIDs ab und empfängt <code>List of DataIDs</code>.</li>\n<li>Der DCM sperrt die Aktualisierung des Datensatzes via <code>Dem_DisableDTCRecordUpdate</code>.</li>\n<li>Der DCM liest die Rohdaten mittels <code>Dem_GetFreezeFrameDataByDTC</code> aus und erhält <code>Snapshot record(s)</code>.</li>\n<li>Der DCM gibt die Aktualisierung über <code>Dem_EnableDTCRecordUpdate</code> wieder frei.</li>\n<li>Der DCM assembliert und übermittelt die UDS-Antwort <code>Response: $59 $05 (DTC + DTCStatus + RecordNumber + Number of Identifiers + SnapshotData)</code> an den External Tester.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>RecordNumbering</strong>: Die Snapshot-Record-Nummern müssen absolut adressiert sein (<code>RecordNumbers must be absolute</code>).</li>\n<li><strong>Konsistenzsicherung</strong>: Das Umschließen des Lesezugriffs (<code>Dem_GetFreezeFrameDataByDTC</code>) mit <code>Dem_DisableDTCRecordUpdate</code> und <code>Dem_EnableDTCRecordUpdate</code> stellt Datenkonsistenz sicher und verhindert Überschreibungen während des Auslesevorgangs.</li>\n<li><strong>Fehlerbehandlung</strong>: Die Sequenz zeigt den Gutfall; bei nicht vorhandenen Record-Nummern oder ungültigen Parametern greifen entsprechende negative Response-Codes (NRCs) bzw. Fehler-Rückgabewerte der DEM-APIs.</li>\n</ul>"}, {"id": "FIG-cd8a5e0cf7d63e09", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Interaktions- und Datenflussdiagramm im Kontext der AUTOSAR Classic Diagnostic Stack-Architektur. Das Diagramm zeigt das strukturelle Rahmenwerk für den UDS-Service 0x19 0x05 (Report DTC Snapshot Record By Snapshot Record Number) mit Interaktionspfeilen zwischen drei unbeschrifteten Entitätsblöcken (Tester, Server-DCM, Diagnosespeicher DEM) sowie einer tabellarischen Speicherstruktur. Sämtliche Beschriftungen der Blöcke, Schnittstellenfunktionen und Payloads fehlen im Diagramminhalt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Drei unbeschriftete Hauptblöcke</strong>: Entsprechen strukturell einem externen Tester, einem Diagnosekommunikationsmanager und einem Diagnosespeicher.</li>\n<li><strong>Speicherstruktur</strong>: Matrix mit 3 Spalten und 3 Zeilen zur Repräsentation von Ereignisspeichereinträgen (ohne Textbeschriftung).</li>\n<li><strong>Schnittstellen</strong>:</li>\n<li>Zwei vertikale Pfeile für UDS-Request und UDS-Response zwischen oberem und linkem Block.</li>\n<li>Fünf horizontale Funktionsaufruf-Pfeile vom linken Block zum rechten Block.</li>\n<li>Drei horizontale Rückgabewert-Pfeile (rot) vom rechten Block zum linken Block.</li>\n<li>Sämtliche API-Namen, Parameter und Nachrichteninhalte sind im Diagramm nicht beschriftet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Diagnoseanfrage wird vom oberen Block an den linken Block übertragen.</li>\n<li>Der linke Block führt sequenziell Funktionsaufrufe an den rechten Block aus:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Erster Aufruf mit synchronem Rückgabewert.</li>\n<li>Zweiter Aufruf mit synchronem Rückgabewert.</li>\n<li>Dritter Aufruf (ohne Rückgabewertpfeil).</li>\n<li>Vierter Aufruf mit synchronem Rückgabewert.</li>\n<li>Fünfter Aufruf (ohne Rückgabewertpfeil).</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Diagnoseantwort wird vom linken Block an den oberen Block zurückgesendet.</li>\n<li>Alle konkreten Funktions- und Payload-Bezeichner sind unbeschriftet.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Durch das vollständige Fehlen der textuellen Annotationen an den Funktions- und Nachrichtenpfeilen liefert das Diagramm für sich allein keine spezifizierten API-Namen, UDS-Payloadstrukturen oder Randbedingungen (wie Adressierungsregeln für Record-Nummern).</li>\n<li>Das Sequenzmuster verdeutlicht auf rein grafischer Ebene eine 5-stufige Interaktion mit Absicherung/Klammerung (Aufrufe 3 und 5 ohne Rückgabepfeil um Aufruf 4) zur Konsistenzwahrung vor der abschließenden Antwortübermittlung.</li>\n</ul>"}], "trans": [{"from": "FIG-0de9f46b40d3ca12", "to": "FIG-cd8a5e0cf7d63e09", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Sämtliche Textbeschriftungen innerhalb der Komponentenblöcke (\"External Tester\", \"DCM\", \"DEM\", \"Event memory\", Tabelleninhalte DTC1/DTC2/free), an den Schnittstellenpfeilen (UDS-Request/Response, C-APIs Dem_GetDTCOfFreezeFrameRecord, Dem_GetFreezeFrameDataIdentifiersByDTC, Dem_DisableDTCRecordUpdate, Dem_GetFreezeFrameDataByDTC, Dem_EnableDTCRecordUpdate, Rückgabewerte) sowie Legende (\"Function call\", \"Return value(s)\") und Fußnote (\"RecordNumbers must be absolute\") fehlen in der Darstellung (Rendering-/Exportfehler des Text-Layers).</li>\n</ul>"}]};
